INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Akzeptanztests immer vom Kunden durchgeführt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch intern möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend Kundenaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Akzeptanztests?', 3, '[{"text": "Kundenanforderungen prüfen", "correct": true, "because": "Sichert Abnahme"}, {"text": "Code optimieren", "correct": false, "because": "Anderer Fokus"}, {"text": "UI gestalten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu Akzeptanztests?', 5, '[{"text": "Anforderungen", "correct": true, "because": "Grundlage der Tests"}, {"text": "Abnahmekriterien", "correct": true, "because": "Definieren Erfolg"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Netzwerkprotokolle", "correct": false, "because": "Technischer Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Akzeptanztests prüfen Funktionalität. b) Sie ersetzen Unit-Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Unit-Tests separat"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Akzeptanztests?', 4, '[{"text": "Kundenanforderungen", "correct": false, "because": "Kern der Tests"}, {"text": "Abnahmekriterien", "correct": false, "because": "Definieren Erfolg"}, {"text": "Serverkonfiguration", "correct": true, "because": "Technischer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Akzeptanztests nur am Ende stattfinden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch iterativ möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Anforderungen zu prüfen?', 3, '[{"text": "Testfälle erstellen", "correct": true, "because": "Spezifiziert Szenarien"}, {"text": "Code kompilieren", "correct": false, "because": "Anderer Zweck"}, {"text": "UI anpassen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Akzeptanztests?', 5, '[{"text": "Kundenzufriedenheit", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Qualitätssicherung", "correct": true, "because": "Bestätigt Funktion"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Akzeptanztests sind nutzerzentriert. b) Sie prüfen nur technische Details. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Fokus auf Anforderungen"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Akzeptanztests?', 4, '[{"text": "Anforderungsdokument", "correct": false, "because": "Basis der Tests"}, {"text": "Testplan", "correct": false, "because": "Strukturiert Durchführung"}, {"text": "3D-Animationen", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Akzeptanztests rein technisch?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Nutzeranforderungen"}, {"text": "Ja", "correct": false, "because": "Kundenorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zu Akzeptanztests?', 4, '[{"text": "Testfälle definieren", "correct": true, "because": "Prüft Anforderungen"}, {"text": "Abnahme bestätigen", "correct": true, "because": "Abschluss des Tests"}, {"text": "Code neu schreiben", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Akzeptanztests nur für Software sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Prozesse nutzbar"}, {"text": "Ja", "correct": false, "because": "Breiter einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Akzeptanztests?', 3, '[{"text": "Kundenerwartungen", "correct": true, "because": "Sichert Zufriedenheit"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}, {"text": "Designanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Akzeptanztests validieren Anforderungen. b) Sie sind immer automatisiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Manuell möglich"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es ohne Akzeptanztests?', 5, '[{"text": "Nicht erfüllte Anforderungen", "correct": true, "because": "Kunde unzufrieden"}, {"text": "Fehlende Abnahme", "correct": true, "because": "Projekt unklar"}, {"text": "Schnellere Lieferung", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Akzeptanztests unwichtig?', 3, '[{"text": "Testkriterien", "correct": false, "because": "Definieren Erfolg"}, {"text": "Kundenfeedback", "correct": false, "because": "Richtet Tests aus"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Prüfen Akzeptanztests technische Details?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Anforderungen"}, {"text": "Ja", "correct": false, "because": "Eher Integrationstests"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Akzeptanztests iterativ sind?', 2, '[{"text": "Ja", "correct": true, "because": "In agilen Projekten üblich"}, {"text": "Nein", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium wähle ich für die Abnahme?', 4, '[{"text": "Erfüllte Anforderungen", "correct": true, "because": "Bestätigt Erfolg"}, {"text": "Code-Performance", "correct": false, "because": "Technischer Fokus"}, {"text": "UI-Design", "correct": false, "because": "Sekundär"}]');
